(7128991, 1091706, 9668, '<td valign="top">Top 10. Awesome coastline. Love the shadow cross the water. Looks like a lovely calm day.</td>', 'Top 10. Awesome coastline. Love the shadow cross the water. Looks like a lovely calm day.', '2013-11-13 00:24:10.000000', NULL, 1),
(7129011, 1091626, 129147, '<td valign="top">Great job on the processing.</td>', 'Great job on the processing.', '2013-11-13 01:01:40.000000', NULL, 1),
(7129012, 1091597, 129147, '<td valign="top">A little overdone for me.</td>', 'A little overdone for me.', '2013-11-13 01:03:48.000000', NULL, 1),
(7129014, 1091841, 129147, '<td valign="top">Pleasing image, colors seem off.</td>', 'Pleasing image, colors seem off.', '2013-11-13 01:04:57.000000', NULL, 1),
(7129015, 1091753, 108580, '<td valign="top">Love it, so out of the box. We are not fish swimming in the mainstream!</td>', 'Love it, so out of the box. We are not fish swimming in the mainstream!', '2013-11-13 01:05:59.000000', NULL, 1),
