(7129018, 1091504, 129147, '<td valign="top">Too dark.</td>', 'Too dark.', '2013-11-13 01:07:29.000000', NULL, 1),
(7129019, 1091538, 129147, '<td valign="top">Horizon needs straightening, blue seems off.</td>', 'Horizon needs straightening, blue seems off.', '2013-11-13 01:08:20.000000', NULL, 1),
