(7129722, 1090758, 143062, '<td valign="top">If the people were not cut off it would be better.</td>', 'If the people were not cut off it would be better.', '2013-11-13 20:58:04.000000', NULL, 1),
(7129725, 1091701, 24846, '<td valign="top">Different touch on the challenge. Nice work/</td>', 'Different touch on the challenge. Nice work/', '2013-11-13 20:58:47.000000', NULL, 1),
(7129727, 1091706, 24846, '<td valign="top">Great image that gives the eye a lot to examine.</td>', 'Great image that gives the eye a lot to examine.', '2013-11-13 20:59:57.000000', NULL, 1),
(7129728, 1091857, 24846, '<td valign="top">Nice composition.</td>', 'Nice composition.', '2013-11-13 21:03:42.000000', NULL, 1),
(7129730, 1091663, 24846, '<td valign="top">I can hear the waves lapping on the shore. Nice shot.</td>', 'I can hear the waves lapping on the shore. Nice shot.', '2013-11-13 21:05:06.000000', NULL, 1),
(7129731, 1091333, 24846, '<td valign="top">Nice capture and exposure.</td>', 'Nice capture and exposure.', '2013-11-13 21:05:57.000000', NULL, 1),
(7129733, 1091584, 24846, '<td valign="top">Nice capture. Wehrspann Lake?</td>', 'Nice capture. Wehrspann Lake?', '2013-11-13 21:08:49.000000', NULL, 1),
(7129734, 1091594, 24846, '<td valign="top">Nice work, like the foreground puddle.</td>', 'Nice work, like the foreground puddle.', '2013-11-13 21:09:53.000000', NULL, 1),
(7129735, 1091643, 24846, '<td valign="top">Really nice symmetry and treatment. Front page image.</td>', 'Really nice symmetry and treatment. Front page image.', '2013-11-13 21:11:35.000000', NULL, 1),
(7129737, 1091828, 24846, '<td valign="top">Nice abstract</td>', 'Nice abstract', '2013-11-13 21:13:06.000000', NULL, 1),
(7129738, 1091674, 24846, '<td valign="top">Really nice math in the exposure and compostion. Love the trees.</td>', 'Really nice math in the exposure and compostion. Love the trees.', '2013-11-13 21:14:48.000000', NULL, 1),
(7129740, 1091080, 24846, '<td valign="top">Nice pastels and balance.</td>', 'Nice pastels and balance.', '2013-11-13 21:18:20.000000', NULL, 1),
(7129741, 1091821, 24846, '<td valign="top">Interesting New England capture. Love the pov and treatment. Should rank ribbon or front page. Good luck!</td>', 'Interesting New England capture. Love the pov and treatment. Should rank ribbon or front page. Good luck!', '2013-11-13 21:21:51.000000', NULL, 1),
(7129742, 1091729, 24846, '<td valign="top">Nice treatment. The fisherman really makes the scene.</td>', 'Nice treatment. The fisherman really makes the scene.', '2013-11-13 21:22:35.000000', NULL, 1),
(7129745, 1091796, 24846, '<td valign="top">Nice shot and processing with this inviting composition.</td>', 'Nice shot and processing with this inviting composition.', '2013-11-13 21:24:52.000000', NULL, 1),
(7129746, 1091786, 10785, '<td valign="top"><strike></strike> this was once an empty comment. I don''t remember commenting or voting in this challenge. So here''s the real comment...the crystal clear water forms the shape of an eye with an interesting crest of water shaping the eye lashes! Nice abstract. <br/><br/><i>Message edited by author 2013-11-27 21:59:58.</i></td>', ' this was once an empty comment. I don''t remember commenting or voting in this challenge. So here''s the real comment...the crystal clear water forms the shape of an eye with an interesting crest of water shaping the eye lashes! Nice abstract. ', '2013-11-13 21:28:44.000000', '2013-11-27 21:59:58.000000', 1),
(7129747, 1091037, 24846, '<td valign="top">A lovely painterly effect.</td>', 'A lovely painterly effect.', '2013-11-13 21:28:44.000000', NULL, 1),
(7129749, 1091291, 24846, '<td valign="top">Nice composition an treatment. A real winner.</td>', 'Nice composition an treatment. A real winner.', '2013-11-13 21:30:08.000000', NULL, 1),
(7129750, 1091575, 24846, '<td valign="top">Great shot.</td>', 'Great shot.', '2013-11-13 21:31:06.000000', NULL, 1),
(7129763, 1091776, 94241, '<td valign="top">Slightly off-balance, heavy on the right.  Consider rotating left a bit?</td>', 'Slightly off-balance, heavy on the right.  Consider rotating left a bit?', '2013-11-13 22:29:30.000000', NULL, 1),
(7129764, 1091773, 94241, '<td valign="top">I once tracked which music I listened to while I post-processed each image.  Results were indeterminate.  Consider trying other drugs?<br/> <br/>+2 for intriguing title.  :)</td>', 'I once tracked which music I listened to while I post-processed each image.  Results were indeterminate.  Consider trying other drugs? +2 for intriguing title.  :)', '2013-11-13 22:32:25.000000', NULL, 1),
(7129765, 1091753, 94241, '<td valign="top">Too clever, not enough water.</td>', 'Too clever, not enough water.', '2013-11-13 22:32:53.000000', NULL, 1),
(7129766, 1091794, 94241, '<td valign="top">This image is upside down -- all the heaviest tones are up on top, the lighter, aerie tones are all down at the bottom.  That''s gonna confuse a lot of your audience.</td>', 'This image is upside down -- all the heaviest tones are up on top, the lighter, aerie tones are all down at the bottom.  That''s gonna confuse a lot of your audience.', '2013-11-13 22:34:42.000000', NULL, 1),
(7129769, 1091740, 94241, '<td valign="top">Every image needs exactly one hero.  This has two: birds and rock.  Should do a bit of darkening in post to reduce the rock and help the viewer focus on the birds.</td>', 'Every image needs exactly one hero.  This has two: birds and rock.  Should do a bit of darkening in post to reduce the rock and help the viewer focus on the birds.', '2013-11-13 22:40:14.000000', NULL, 1),
(7129770, 1090657, 94241, '<td valign="top">A lil'' overexposed.  Perhaps even just a vignette.<br/> <br/>I love this bridge.  :)</td>', 'A lil'' overexposed.  Perhaps even just a vignette. I love this bridge.  :)', '2013-11-13 22:41:46.000000', NULL, 1),
(7129771, 1091829, 94241, '<td valign="top">The border is a little strong.  Let the image stand on its own.  It''s a good image.  :)</td>', 'The border is a little strong.  Let the image stand on its own.  It''s a good image.  :)', '2013-11-13 22:44:59.000000', NULL, 1),
(7129772, 1091664, 94241, '<td valign="top">I like the scenery, but the brush in front just kinda is a barrier between the audience and the hero light beyond.</td>', 'I like the scenery, but the brush in front just kinda is a barrier between the audience and the hero light beyond.', '2013-11-13 22:46:29.000000', NULL, 1),
(7129774, 1091747, 94241, '<td valign="top">Black and white is all about a very careful control of the tones and exposure.</td>', 'Black and white is all about a very careful control of the tones and exposure.', '2013-11-13 22:50:18.000000', NULL, 1),
(7129775, 1091674, 94241, '<td valign="top">Beautiful scene.<br/> <br/>Compositionally there are two heroes in this shot: the river and the trees.  If the image was recomposed to favor one over the other, I think it would be stronger.  A little lower tilting up, or a little higher tilting down.  It''s just too even.</td>', 'Beautiful scene. Compositionally there are two heroes in this shot: the river and the trees.  If the image was recomposed to favor one over the other, I think it would be stronger.  A little lower tilting up, or a little higher tilting down.  It''s just too even.', '2013-11-13 22:52:46.000000', NULL, 1),
(7129776, 1091788, 94241, '<td valign="top">I feel your pain bro.  *fistbump*<br/> <br/>So, brush in a little brightness on the reflection in the lower right, kay?  And add a bit of a vignette.</td>', 'I feel your pain bro.  *fistbump* So, brush in a little brightness on the reflection in the lower right, kay?  And add a bit of a vignette.', '2013-11-13 22:54:46.000000', NULL, 1),
(7129777, 1091651, 94241, '<td valign="top">A vignette would add a lot of depth to this.</td>', 'A vignette would add a lot of depth to this.', '2013-11-13 22:55:56.000000', NULL, 1),
(7129778, 1091854, 94241, '<td valign="top">Dude, not a flattering photo -- it''s kinda voyeristic and creepy.</td>', 'Dude, not a flattering photo -- it''s kinda voyeristic and creepy.', '2013-11-13 22:57:24.000000', NULL, 1),
(7129779, 1091364, 94241, '<td valign="top">Fantastic tones.  Would love a little more zoomed in, seems like a bit of wasted vertical space.</td>', 'Fantastic tones.  Would love a little more zoomed in, seems like a bit of wasted vertical space.', '2013-11-13 23:00:18.000000', NULL, 1),
(7129780, 1090873, 94241, '<td valign="top">Makes me hold my breath for the stillness.  Awesome.  :)<br/> <br/>A little top-heavy, would have cropped a bit more on the bottom, wider aspect ratio?</td>', 'Makes me hold my breath for the stillness.  Awesome.  :) A little top-heavy, would have cropped a bit more on the bottom, wider aspect ratio?', '2013-11-13 23:01:52.000000', NULL, 1),
(7129781, 1090885, 94241, '<td valign="top">Nice use of purple, dude.</td>', 'Nice use of purple, dude.', '2013-11-13 23:02:46.000000', NULL, 1),
(7129782, 1091857, 94241, '<td valign="top">Hey, I''ve been there.  Awesome image; I''m jelly.  :)</td>', 'Hey, I''ve been there.  Awesome image; I''m jelly.  :)', '2013-11-13 23:04:27.000000', NULL, 1),
(7129783, 1091818, 94241, '<td valign="top">The power of this image is its rhythm.  The weakness is its clutter.  I say this with much love, because I really like this image.  &lt;3</td>', 'The power of this image is its rhythm.  The weakness is its clutter.  I say this with much love, because I really like this image.  <3', '2013-11-13 23:07:03.000000', NULL, 1),
(7129784, 1091719, 94241, '<td valign="top">Something about the arrangement itself is disturbing.<br/> <br/>Absolute beautiful and considered composition.  I grant you that.  :)<br/> <br/>Just, frightening somehow.<br/> <br/> <br/>* Disclaimer: gay guy.  Think it''s vaguely feminine?</td>', 'Something about the arrangement itself is disturbing. Absolute beautiful and considered composition.  I grant you that.  :) Just, frightening somehow.  * Disclaimer: gay guy.  Think it''s vaguely feminine?', '2013-11-13 23:10:35.000000', NULL, 1),
(7129785, 1091473, 94241, '<td valign="top">Holy poop, beautiful.  :)<br/> <br/>Tad heavy on the left, a wee little bit of rotation, maybe?</td>', 'Holy poop, beautiful.  :) Tad heavy on the left, a wee little bit of rotation, maybe?', '2013-11-13 23:11:59.000000', NULL, 1),
(7129786, 1091750, 94241, '<td valign="top">Two heros: the bridge and the ripples.  Compositionally I think you should choose one and favor it more.  So, a tad higher looking down, or a tad lower looking up.  It''s just too even right now.</td>', 'Two heros: the bridge and the ripples.  Compositionally I think you should choose one and favor it more.  So, a tad higher looking down, or a tad lower looking up.  It''s just too even right now.', '2013-11-13 23:13:29.000000', NULL, 1),
(7129787, 1091016, 94241, '<td valign="top">I see Yin-Yang.  :)</td>', 'I see Yin-Yang.  :)', '2013-11-13 23:13:47.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7129789, 1091626, 94241, '<td valign="top">Magical scene, but a little broody and mad.  Maybe a more cheery palette?  Or brighter?  :)</td>', 'Magical scene, but a little broody and mad.  Maybe a more cheery palette?  Or brighter?  :)', '2013-11-13 23:15:16.000000', NULL, 1),
(7129790, 1091512, 94241, '<td valign="top">Gorgeous, but the boat is too much.</td>', 'Gorgeous, but the boat is too much.', '2013-11-13 23:18:47.000000', NULL, 1),
(7129799, 1091711, 15511, '<td valign="top">I love the "working quay" look to this image. I''ve <a href="//home.comcast.net/~cx50079/TT2007/Sights/PortStMaryB/index.html" rel="nofollow" target="_blank">seen that boat before</a>. It was back in ''07 in the Isle of Man. Just a small world, isn''t it?</td>', 'I love the "working quay" look to this image. I''ve seen that boat before. It was back in ''07 in the Isle of Man. Just a small world, isn''t it?', '2013-11-13 23:51:33.000000', NULL, 1),
(7129805, 1091853, 86218, '<td valign="top">Wow.. so much potential in this shot. To much dead space in the FG. Had every opportunity to ribbon here with this light, scenery and mood. Great effort none the less</td>', 'Wow.. so much potential in this shot. To much dead space in the FG. Had every opportunity to ribbon here with this light, scenery and mood. Great effort none the less', '2013-11-14 00:12:53.000000', NULL, 1),
(7129807, 1091500, 86218, '<td valign="top">Im trying to gel with this comp given that which you have to work with. Lovely colours, river and small falls. Not sure that the left contributes to this in any way and the image lies in background and whats right in front here. This presents a nice overall view of the setting, but maybe could have been stronger with a different take?</td>', 'Im trying to gel with this comp given that which you have to work with. Lovely colours, river and small falls. Not sure that the left contributes to this in any way and the image lies in background and whats right in front here. This presents a nice overall view of the setting, but maybe could have been stronger with a different take?', '2013-11-14 00:18:09.000000', NULL, 1),
(7129876, 1090905, 86218, '<td valign="top">A nice shot. A tad heavy on the sky.. but Im looking at certain section of this image and Im asking myself....WOW.. there are brilliant other parts which I would have focused on. Maybe the clouds have been worked to much due to some HDR type processing. A serene place sure to be revisited by you...this is a photographers dream spot</td>', 'A nice shot. A tad heavy on the sky.. but Im looking at certain section of this image and Im asking myself....WOW.. there are brilliant other parts which I would have focused on. Maybe the clouds have been worked to much due to some HDR type processing. A serene place sure to be revisited by you...this is a photographers dream spot', '2013-11-14 07:35:36.000000', NULL, 1),
(7129997, 1091711, 172706, '<td valign="top">Home!</td>', 'Home!', '2013-11-14 17:39:11.000000', NULL, 1),
(7130003, 1091016, 100773, '<td valign="top">First of all I don''t like the toning here. The balance in shadows and high lights seems a bit random. I would''ve darkened that rocky surface in the right corner and brightened the reflections on the left side to match those under the brdge. The background for me takes to much focus, so I would''ve darkened it or shot it with a lower depth of field. <br/> <br/>But don''t get me wrong here because I do like this photo alot! The scene itself is beautifull and I wish I''d been there to capture it myself. The things I would do differently is not the correct way. Your way is the correct way, and we learn from experiences and the feedback we choose to listen to as we go along. 8 from me</td>', 'First of all I don''t like the toning here. The balance in shadows and high lights seems a bit random. I would''ve darkened that rocky surface in the right corner and brightened the reflections on the left side to match those under the brdge. The background for me takes to much focus, so I would''ve darkened it or shot it with a lower depth of field.  But don''t get me wrong here because I do like this photo alot! The scene itself is beautifull and I wish I''d been there to capture it myself. The things I would do differently is not the correct way. Your way is the correct way, and we learn from experiences and the feedback we choose to listen to as we go along. 8 from me', '2013-11-14 18:20:04.000000', NULL, 1),
(7130006, 1090945, 100773, '<td valign="top">This is not for me at all, sorry. This for me is like a chef thinking it''s a great idea to take a French appetizer, a Norwegian main course and an Indian dessert and mix them all in a blender. This is split toning, black and white and over saturating. I would go for one effect at the time. Score 2 from me, since you''re on topic</td>', 'This is not for me at all, sorry. This for me is like a chef thinking it''s a great idea to take a French appetizer, a Norwegian main course and an Indian dessert and mix them all in a blender. This is split toning, black and white and over saturating. I would go for one effect at the time. Score 2 from me, since you''re on topic', '2013-11-14 18:25:26.000000', NULL, 1),
(7130008, 1091717, 100773, '<td valign="top">There''s something about this that seems off balanced in a way, I think it''s the bright area in front of the dog, and the current in the foreground doesn''t add to the photograph in any way; the water is already beautifully presented. The story in the photo is good, and I like the colors. 7, since I''m a dog owner and lover</td>', 'There''s something about this that seems off balanced in a way, I think it''s the bright area in front of the dog, and the current in the foreground doesn''t add to the photograph in any way; the water is already beautifully presented. The story in the photo is good, and I like the colors. 7, since I''m a dog owner and lover', '2013-11-14 18:27:40.000000', NULL, 1),
(7130009, 1091835, 100773, '<td valign="top">It has a film quality look to it that I''m instinctually rejecting because I hate digital trying to behave analog. That being said this is a beautifull photograph that should be rewarded for what it is; a beautifull photograph. 8</td>', 'It has a film quality look to it that I''m instinctually rejecting because I hate digital trying to behave analog. That being said this is a beautifull photograph that should be rewarded for what it is; a beautifull photograph. 8', '2013-11-14 18:34:46.000000', NULL, 1),
(7130010, 1091729, 100773, '<td valign="top">I would''ve darkened the background since the action is the fisherman. Or done the complete opposite; focused on the background making it look good and hid the fisherman further down in the right corner as a pleasant surprise for those looking at a photo for more than 5 seconds. Now it kinda looks like both is in focus, and that makes it messy for me. 6</td>', 'I would''ve darkened the background since the action is the fisherman. Or done the complete opposite; focused on the background making it look good and hid the fisherman further down in the right corner as a pleasant surprise for those looking at a photo for more than 5 seconds. Now it kinda looks like both is in focus, and that makes it messy for me. 6', '2013-11-14 18:39:03.000000', NULL, 1),
(7130100, 1091643, 108580, '<td valign="top">This is very beautifully done at a very popular spot :) The processing is wonderful and you must have had the hide to yourself to get a long exposure without wobble. Pity they have placed those darn fake perches for the birds... Maybe no one else will notice. Could be one of three togs I know.</td>', 'This is very beautifully done at a very popular spot :) The processing is wonderful and you must have had the hide to yourself to get a long exposure without wobble. Pity they have placed those darn fake perches for the birds... Maybe no one else will notice. Could be one of three togs I know.', '2013-11-15 01:02:09.000000', NULL, 1),
(7130180, 1091194, 100773, '<td valign="top">I think it''s a bit grey, but it kinds suits it as well. A nice photograph. 8</td>', 'I think it''s a bit grey, but it kinds suits it as well. A nice photograph. 8', '2013-11-15 04:32:32.000000', NULL, 1),
(7130185, 1091642, 100773, '<td valign="top">A good capture! 8</td>', 'A good capture! 8', '2013-11-15 04:37:18.000000', NULL, 1),
(7130186, 1091536, 100773, '<td valign="top">I think this is a very pleasant photograph. 10</td>', 'I think this is a very pleasant photograph. 10', '2013-11-15 04:37:50.000000', NULL, 1),
(7130188, 1091614, 100773, '<td valign="top">Back lit landscapes are difficult to shoot because you will always have a very bright area, but this has a good feel to it and is technically ok performed. 7</td>', 'Back lit landscapes are difficult to shoot because you will always have a very bright area, but this has a good feel to it and is technically ok performed. 7', '2013-11-15 04:38:49.000000', NULL, 1),
(7130189, 1091364, 100773, '<td valign="top">The colors are a bit dull, but I like it as it is. Good job! 9</td>', 'The colors are a bit dull, but I like it as it is. Good job! 9', '2013-11-15 04:39:19.000000', NULL, 1),
(7130203, 1091372, 100773, '<td valign="top">The duck coud benefit from a bit more contrast, and the ducks path in the water could also be enhanced in some way. Darkened the V shape behind it maybe. 6</td>', 'The duck coud benefit from a bit more contrast, and the ducks path in the water could also be enhanced in some way. Darkened the V shape behind it maybe. 6', '2013-11-15 05:50:00.000000', NULL, 1),
(7130337, 1091080, 119804, '<td valign="top">Fantastically Simple, I love it!</td>', 'Fantastically Simple, I love it!', '2013-11-15 13:09:45.000000', NULL, 1),
(7130340, 1091828, 119804, '<td valign="top">Love the Colours... I Love it</td>', 'Love the Colours... I Love it', '2013-11-15 13:11:59.000000', NULL, 1),
(7130341, 1091719, 119804, '<td valign="top">Well Framed, Great Contrast.</td>', 'Well Framed, Great Contrast.', '2013-11-15 13:13:14.000000', NULL, 1),
(7130367, 1091674, 108580, '<td valign="top">Wonderfully sought out, photographed and PP. I hope it''s pulling in 7''s + as it should (Team 1 TPL2 Team MAte, no vote mores the pity).</td>', 'Wonderfully sought out, photographed and PP. I hope it''s pulling in 7''s + as it should (Team 1 TPL2 Team MAte, no vote mores the pity).', '2013-11-15 14:50:41.000000', NULL, 1),
(7130369, 1091573, 108580, '<td valign="top">Lovely vibrant and wonderful spray caught.<br/><br/><i>Message edited by author 2013-11-20 01:03:28.</i></td>', 'Lovely vibrant and wonderful spray caught.', '2013-11-15 14:52:10.000000', '2013-11-20 01:03:28.000000', 1),
(7130370, 1091661, 108580, '<td valign="top">I was surprised you chose this one. It is a feel good image; father and son fishing (2 rods), nice lead in lines, ominous clouds but I fear the pier to be more prominent than the "Large Body of Water" (No Vote, Team1 TPL2 Team Mate)</td>', 'I was surprised you chose this one. It is a feel good image; father and son fishing (2 rods), nice lead in lines, ominous clouds but I fear the pier to be more prominent than the "Large Body of Water" (No Vote, Team1 TPL2 Team Mate)', '2013-11-15 14:52:16.000000', NULL, 1),
(7130402, 1091827, 16106, '<td valign="top">Its tough getting the close stuff in focus without letting the stuff way way back in the reflection going out of focus, but it is essential in this sort of shot. Here the vague softness of the textures in the foreground steals  much of what is n1ce in this shot.</td>', 'Its tough getting the close stuff in focus without letting the stuff way way back in the reflection going out of focus, but it is essential in this sort of shot. Here the vague softness of the textures in the foreground steals  much of what is n1ce in this shot.', '2013-11-15 17:31:53.000000', NULL, 1),
(7130403, 1091818, 16106, '<td valign="top">It is a great sky but the framing puts so much attention on the drama up there that the water can not compete. Pushed down into the lower fifth of the frame, what should be your star ends up in the back of the chorus.</td>', 'It is a great sky but the framing puts so much attention on the drama up there that the water can not compete. Pushed down into the lower fifth of the frame, what should be your star ends up in the back of the chorus.', '2013-11-15 17:34:43.000000', NULL, 1),
(7130405, 1090702, 16106, '<td valign="top">A better shot than an entry. The image is first rate, but the water and the rich sky create the context for the buildings which are the star of the show. I want to honor the quality of the image, but am not sure how well you rose to the challenge. I will vote after I think about that dilemma more.</td>', 'A better shot than an entry. The image is first rate, but the water and the rich sky create the context for the buildings which are the star of the show. I want to honor the quality of the image, but am not sure how well you rose to the challenge. I will vote after I think about that dilemma more.', '2013-11-15 17:38:45.000000', NULL, 1),
(7130406, 1091701, 16106, '<td valign="top">In the attempt to give context, you lost a lot of the drama. That churn of ice and flow look amazing, but most of the image is slightly over saturated trees and rocks. All I want to see is the star of the show and it fills so little of the frame.</td>', 'In the attempt to give context, you lost a lot of the drama. That churn of ice and flow look amazing, but most of the image is slightly over saturated trees and rocks. All I want to see is the star of the show and it fills so little of the frame.', '2013-11-15 17:41:51.000000', NULL, 1),
(7130407, 1091575, 16106, '<td valign="top">I''m not sure how long the exposure is here, but the water, which should be the star of the show, has been reduced to a flat grey sheet. It is a pretty image and the rest of the shot is powerful, but the water looks more like a negative space, imparting no drama and only the slighted reflections of the buildings. Another in a run of nice images where I m having trouble scoring them.</td>', 'I''m not sure how long the exposure is here, but the water, which should be the star of the show, has been reduced to a flat grey sheet. It is a pretty image and the rest of the shot is powerful, but the water looks more like a negative space, imparting no drama and only the slighted reflections of the buildings. Another in a run of nice images where I m having trouble scoring them.', '2013-11-15 17:46:35.000000', NULL, 1),
(7130409, 1091852, 16106, '<td valign="top">I love the turgid motion of the water offset by the slanting rays of light, but I miss the details, on my monitor it seems a tad soft. Had that detail been there it would have been among my favorites as everything else is strong.</td>', 'I love the turgid motion of the water offset by the slanting rays of light, but I miss the details, on my monitor it seems a tad soft. Had that detail been there it would have been among my favorites as everything else is strong.', '2013-11-15 17:55:17.000000', NULL, 1),
(7130411, 1091854, 163469, '<td valign="top">very clever6 for originality!</td>', 'very clever6 for originality!', '2013-11-15 18:21:45.000000', NULL, 1),
(7130416, 1091762, 97225, '<td valign="top">I really love this. I could look at it for hours and then come back later and do the same. 10 and a fave.</td>', 'I really love this. I could look at it for hours and then come back later and do the same. 10 and a fave.', '2013-11-15 18:36:44.000000', NULL, 1),
(7130419, 1091706, 97225, '<td valign="top">Beautiful location, gorgeous colours.</td>', 'Beautiful location, gorgeous colours.', '2013-11-15 18:38:20.000000', NULL, 1),
