(7132008, 1091682, 54446, '<td valign="top">Tilted.</td>', 'Tilted.', '2013-11-19 12:24:38.000000', NULL, 1),
(7132063, 1091785, 30861, '<td valign="top">The HORIZON, danggit! It would make SUCH a difference...</td>', 'The HORIZON, danggit! It would make SUCH a difference...', '2013-11-19 14:23:09.000000', NULL, 1),
(7132066, 1091291, 30861, '<td valign="top">Makes me think of Frost: "These flowery waters and these watery flowers / From snow that melted only yesterday..."<br/> <br/>Gorgeous scene. Do they have internet access? If so, I''m moving :-)<br/><br/><i>Message edited by author 2013-11-20 15:31:29.</i></td>', 'Makes me think of Frost: "These flowery waters and these watery flowers / From snow that melted only yesterday..." Gorgeous scene. Do they have internet access? If so, I''m moving :-)', '2013-11-19 14:30:55.000000', '2013-11-20 15:31:29.000000', 1),
(7132070, 1091642, 30861, '<td valign="top">Actually, the early WORM gets the HOOK, don''tcha think? Cool mist shot, hard to do well.</td>', 'Actually, the early WORM gets the HOOK, don''tcha think? Cool mist shot, hard to do well.', '2013-11-19 14:37:32.000000', NULL, 1),
(7132071, 1090885, 30861, '<td valign="top">Bingo! Right at the end of my voting queue! 10!</td>', 'Bingo! Right at the end of my voting queue! 10!', '2013-11-19 14:39:11.000000', NULL, 1),
(7132083, 1091291, 86218, '<td valign="top">Lovely shot.. Bump. Imagine this with no wind on those waters and having more reflections of those ridges . The light just marvelous. Smoke a further plus and a perfect tourist shot. I want to know where this is and go there</td>', 'Lovely shot.. Bump. Imagine this with no wind on those waters and having more reflections of those ridges . The light just marvelous. Smoke a further plus and a perfect tourist shot. I want to know where this is and go there', '2013-11-19 15:16:44.000000', NULL, 1),
(7132084, 1091536, 86218, '<td valign="top">This shot just has magic written all over it, eerie feel, a mood and a sense of calm. Great light. Uncertain how it would do however and Im hoping it scores top 10. Voted earlier</td>', 'This shot just has magic written all over it, eerie feel, a mood and a sense of calm. Great light. Uncertain how it would do however and Im hoping it scores top 10. Voted earlier', '2013-11-19 15:18:34.000000', NULL, 1),
(7132138, 1091522, 147314, '<td valign="top">Lovely golden colours and great atmosphere!</td>', 'Lovely golden colours and great atmosphere!', '2013-11-19 18:24:17.000000', NULL, 1),
(7132139, 1091857, 147314, '<td valign="top">Really like the processing, great image.</td>', 'Really like the processing, great image.', '2013-11-19 18:24:54.000000', NULL, 1),
(7132140, 1091762, 147314, '<td valign="top">Does remind me of a drawing of M.C. Escher. Great reflections!</td>', 'Does remind me of a drawing of M.C. Escher. Great reflections!', '2013-11-19 18:27:16.000000', NULL, 1),
(7132142, 1091120, 147314, '<td valign="top">Lovely image, the orange/brown colours of the leaves really work well in this image</td>', 'Lovely image, the orange/brown colours of the leaves really work well in this image', '2013-11-19 18:29:22.000000', NULL, 1),
